import { useState } from "react";
import { Card, CardHeader, RoleWordsTable } from "ui";

const start = [
  { key: "fabrication-lead", name: "Fabrication lead", word: "fab_lead", included: true, waits: true },
  { key: "laser-operator", name: "Laser operator", word: "", included: true },
  { key: "wood-shop-supervisor", name: "Wood shop supervisor", word: "woodshop", included: true, changed: true, notes: ["Was `wood-shop-supervisor`."] },
  { key: "printer-member", name: "3D printer member", word: "", included: false },
];

function Table({ readOnly = false, dense = false }: { readOnly?: boolean; dense?: boolean }) {
  const [rows, setRows] = useState(start);
  const patch = (key: string, p: Partial<(typeof start)[number]>) =>
    setRows((all) => all.map((r) => (r.key === key ? { ...r, ...p } : r)));
  return (
    <Card>
      <CardHeader title="What Print Queue is told" />
      <RoleWordsTable
        app="Print Queue"
        rows={rows}
        readOnly={readOnly}
        dense={dense}
        onWord={(key, word) => patch(key, { word })}
        onIncluded={(key, included) => patch(key, { included })}
      />
    </Card>
  );
}

/** Role, the word the app sees, Included. A to Z by name; a role left out can't be edited until it is ticked. */
export const Editable = () => <Table />;
/** The claims editor's one-line form. */
export const Dense = () => <Table dense />;
export const ReadOnly = () => <Table readOnly />;
